CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,display_name text NOT NULL DEFAULT 'Rebuy member' CHECK(char_length(btrim(display_name)) BETWEEN 1 AND 80),avatar_url text,points integer NOT NULL DEFAULT 0 CHECK(points>=0),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO anon,authenticated;
GRANT UPDATE(display_name,avatar_url) ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public profile names and points" ON public.profiles FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Edit own profile" ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.rebuy_create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(nullif(btrim(NEW.raw_user_meta_data->>'full_name'),''),'Rebuy member'),80)) ON CONFLICT(id) DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER rebuy_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.rebuy_create_profile();
INSERT INTO public.profiles(id,display_name) SELECT id,left(coalesce(nullif(btrim(raw_user_meta_data->>'full_name'),''),'Rebuy member'),80) FROM auth.users ON CONFLICT(id) DO NOTHING;
CREATE TABLE public.points_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,request_id uuid REFERENCES public.requests(id) ON DELETE SET NULL,points integer NOT NULL CHECK(points IN (5,10)),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,request_id));
GRANT SELECT ON public.points_ledger TO authenticated;
GRANT ALL ON public.points_ledger TO service_role;
ALTER TABLE public.points_ledger ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own point history" ON public.points_ledger FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TYPE public.listing_type AS ENUM ('give','exchange');
ALTER TABLE public.items ADD COLUMN listing_type public.listing_type NOT NULL DEFAULT 'give',ADD COLUMN wants text CHECK(char_length(wants)<=200);
ALTER TABLE public.requests ADD COLUMN offer_item_id uuid REFERENCES public.items(id) ON DELETE SET NULL;
CREATE FUNCTION public.rebuy_validate_offer() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN IF NEW.offer_item_id IS DISTINCT FROM OLD.offer_item_id THEN RAISE EXCEPTION 'The offered item cannot be changed'; END IF; RETURN NEW; END IF; IF NOT EXISTS(SELECT 1 FROM public.items WHERE id=NEW.item_id AND user_id=NEW.owner_id AND is_available) THEN RAISE EXCEPTION 'Invalid item owner or unavailable item'; END IF; IF EXISTS(SELECT 1 FROM public.items WHERE id=NEW.item_id AND listing_type='exchange') THEN IF NEW.offer_item_id IS NULL OR NEW.offer_item_id=NEW.item_id OR NOT EXISTS(SELECT 1 FROM public.items WHERE id=NEW.offer_item_id AND user_id=NEW.requester_id AND is_available) THEN RAISE EXCEPTION 'Offer an available item of your own'; END IF; ELSIF NEW.offer_item_id IS NOT NULL THEN RAISE EXCEPTION 'Free items do not require an exchange'; END IF; RETURN NEW; END $$;
CREATE TRIGGER requests_offer_validation BEFORE INSERT OR UPDATE ON public.requests FOR EACH ROW EXECUTE FUNCTION public.rebuy_validate_offer();
CREATE FUNCTION public.rebuy_award_points() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='completed' AND OLD.status IS DISTINCT FROM 'completed' THEN IF auth.uid() IS DISTINCT FROM NEW.owner_id THEN RAISE EXCEPTION 'Only the giver may complete this handover'; END IF; IF NEW.offer_item_id IS NOT NULL THEN PERFORM 1 FROM public.items WHERE id=NEW.offer_item_id FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM public.items WHERE id=NEW.offer_item_id AND user_id=NEW.requester_id AND is_available) THEN RAISE EXCEPTION 'Offered item is no longer available'; END IF; END IF; INSERT INTO public.points_ledger(user_id,request_id,points,reason) VALUES(NEW.owner_id,NEW.id,10,'Item given away'),(NEW.requester_id,NEW.id,5,'Item received'); UPDATE public.profiles SET points=points+CASE WHEN id=NEW.owner_id THEN 10 ELSE 5 END WHERE id IN(NEW.owner_id,NEW.requester_id); UPDATE public.items SET is_available=false WHERE id=NEW.item_id OR id=NEW.offer_item_id; END IF; RETURN NEW; END $$;
CREATE TRIGGER requests_award_points AFTER UPDATE ON public.requests FOR EACH ROW EXECUTE FUNCTION public.rebuy_award_points();
CREATE FUNCTION public.rebuy_protect_listing() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.user_id IS DISTINCT FROM OLD.user_id THEN RAISE EXCEPTION 'Item ownership cannot be changed'; END IF; IF NEW.listing_type IS DISTINCT FROM OLD.listing_type AND EXISTS(SELECT 1 FROM public.requests WHERE item_id=OLD.id) THEN RAISE EXCEPTION 'Listing type cannot change after a request'; END IF; IF NEW.is_available AND NOT OLD.is_available AND EXISTS(SELECT 1 FROM public.requests WHERE (item_id=OLD.id OR offer_item_id=OLD.id) AND status='completed') THEN RAISE EXCEPTION 'Completed handovers cannot be relisted'; END IF; RETURN NEW; END $$;
CREATE TRIGGER items_protect_listing BEFORE UPDATE ON public.items FOR EACH ROW EXECUTE FUNCTION public.rebuy_protect_listing();
CREATE FUNCTION public.rebuy_community_totals() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('items',(SELECT count(*) FROM public.items),'handovers',(SELECT count(*) FROM public.requests WHERE status='completed'),'donors',(SELECT count(*) FROM public.profiles WHERE points>0)); $$;
REVOKE ALL ON FUNCTION public.rebuy_community_totals() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rebuy_community_totals() TO anon,authenticated;
CREATE FUNCTION public.rebuy_given_count(member_id uuid) RETURNS bigint LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT count(*) FROM public.requests WHERE owner_id=member_id AND status='completed'; $$;
REVOKE ALL ON FUNCTION public.rebuy_given_count(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rebuy_given_count(uuid) TO anon,authenticated;
CREATE INDEX items_listing_type_idx ON public.items(listing_type);
CREATE INDEX profiles_points_idx ON public.profiles(points DESC);
CREATE INDEX ledger_user_idx ON public.points_ledger(user_id,created_at DESC);